namespace sv_0930f6319aa446e09e8daf176832390a.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding theme state for the current circuit.
/// In per-page interactive mode every component on a page (including interactive
/// islands in the static layout) shares the same circuit and therefore the same
/// instance of this service.  Cross-navigation persistence is handled via cookies.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd"; // Bootstrap primary

    public event Action? OnThemeChanged;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnThemeChanged?.Invoke();
    }

    public void SetAccentColor(string accentColor)
    {
        if (AccentColor == accentColor) return;
        AccentColor = accentColor;
        OnThemeChanged?.Invoke();
    }

    /// <summary>
    /// Hydrate state from cookie values read during SSR or via JS interop.
    /// </summary>
    public void Initialize(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
    }
}

// Cookie helpers
function setCookie(name, value, days = 400) {
    const expires = new Date(Date.now() + days * 864e5).toUTCString();
    document.cookie = `${name}=${encodeURIComponent(value)};expires=${expires};path=/;SameSite=Lax`;
}

function getCookie(name) {
    const match = document.cookie.match(new RegExp('(?:^|; )' + name + '=([^;]*)'));
    return match ? decodeURIComponent(match[1]) : null;
}

// Apply theme to the DOM so both static and interactive content updates instantly.
function applyTheme(theme, accentColor) {
    const root = document.documentElement;

    // Resolve "system" to actual preference
    let resolved = theme;
    if (theme === 'System') {
        resolved = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'Dark' : 'Light';
    }
    root.setAttribute('data-bs-theme', resolved.toLowerCase());

    if (accentColor) {
        root.style.setProperty('--app-accent-color', accentColor);
    }
}

// Called from interactive components to persist + apply in one shot.
export function setTheme(theme, accentColor) {
    setCookie('app-theme', theme);
    setCookie('app-accent-color', accentColor);
    applyTheme(theme, accentColor);
}

// Read persisted values from cookies (used during interactive init).
export function getTheme() {
    return {
        theme: getCookie('app-theme') || 'System',
        accentColor: getCookie('app-accent-color') || '#0d6efd'
    };
}

// Listen for OS dark-mode changes when theme is "System".
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
    const current = getCookie('app-theme') || 'System';
    if (current === 'System') {
        applyTheme('System', getCookie('app-accent-color') || '#0d6efd');
    }
});

