toolArgs.file_text:
@* 
    Interactive wrapper placed inside the static layout.
    Reads the theme from cookies via JS interop on init, hydrates the scoped
    ThemeService, and applies the theme to the DOM.  Because this component and
    the page's interactive components share the same circuit, they share the
    same ThemeService instance — so changes made on any page are immediately
    visible in the header indicator.
*@
@rendermode InteractiveServer
@inject Services.ThemeService ThemeService
@inject IJSRuntime JS
@implements IAsyncDisposable

@ChildContent

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _module = await JS.InvokeAsync<IJSObjectReference>("import", "./js/theme.js");

        // Read persisted values from cookies
        var stored = await _module.InvokeAsync<ThemeDto>("getTheme");

        if (Enum.TryParse<Services.ThemeMode>(stored.Theme, true, out var mode))
        {
            ThemeService.Initialize(mode, stored.AccentColor ?? "#0d6efd");
        }

        // Apply to DOM so the page matches immediately
        await _module.InvokeVoidAsync("setTheme",
            ThemeService.Theme.ToString(), ThemeService.AccentColor);

        ThemeService.OnThemeChanged += PersistTheme;
    }

    private void PersistTheme()
    {
        _ = InvokeAsync(async () =>
        {
            if (_module is not null)
            {
                await _module.InvokeVoidAsync("setTheme",
                    ThemeService.Theme.ToString(), ThemeService.AccentColor);
            }
        });
    }

    public async ValueTask DisposeAsync()
    {
        ThemeService.OnThemeChanged -= PersistTheme;
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }

    private sealed class ThemeDto
    {
        public string Theme { get; set; } = "System";
        public string AccentColor { get; set; } = "#0d6efd";
    }
}

