toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@inject Services.ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
            {
                <button type="button"
                        class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeService.SetTheme(mode)">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title mt-3">Accent Color</h5>

        <div class="d-flex align-items-center gap-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentColorChanged" />
            <span class="text-muted">@ThemeService.AccentColor</span>
        </div>

        <div class="mt-4 p-3 rounded"
             style="background-color: var(--app-accent-color, @ThemeService.AccentColor); color: white;">
            Preview: This box uses your accent color.
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += HandleThemeChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }
}

